package cn.mop.api;
import cn.mop.domain.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CapacityEstimateControllerTest {
    static final String ACTOR="65000000-0000-4000-8000-000000000001",TENANT="65000000-0000-4000-8000-000000000002";
    PlatformRepository platform;CapacityEstimateController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new CapacityEstimateController(platform);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,true)));}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("POST","/api/v1/capacity/estimates");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","capacity-test");return r;}
    ObjectNode input(){var v=mapper.createObjectNode();v.putObject("inputs").put("hosts","10").put("items_per_host","100").put("interval_seconds","10").put("history_days",2).put("bytes_per_value","80").put("trend_ratio","0.5").put("trend_days",3).put("headroom_ratio","0.25");v.putObject("model").put("version","SYNTHETIC-ONLY-v1").put("bytes_per_trend_row","128").put("pool_nvps_limit","60");v.putObject("proxy_buffer").put("site_nvps","125").put("outage_seconds","3600").put("bytes_per_value","80").put("margin_factor","1.4");return v;}
    Map<?,?> data(JsonNode input,MockHttpServletRequest request){return (Map<?,?>)((Map<?,?>)controller.calculate(input,request)).get("data");}
    @Test void nineOutputsAndBufferMatchExplicitHandValuesAndRemainStrings(){var d=data(input(),request());var o=(Map<?,?>)d.get("outputs");assertEquals(Map.of("nvps","100","daily_bytes","691200000","history_bytes","1382400000","trend_bytes","4608000","single_node_bytes","1733760000","two_node_bytes","3467520000","peak_nvps","200","total_items","1000","pools","2"),o);assertEquals("50400000",((Map<?,?>)d.get("proxy_buffer")).get("estimated_bytes"));assertEquals(TENANT,d.get("tenant_id"));assertEquals("DECIMAL128",d.get("decimal_precision"));assertEquals("BASE10_STRINGS",d.get("decimal_encoding"));}
    @Test void unknownsReturnMissingListsAndNeverSupplyPrototypeValues(){var body=mapper.createObjectNode().putNull("inputs").putNull("model").putNull("proxy_buffer");var d=data(body,request());assertEquals("UNRESOLVED",d.get("status"));assertNull(d.get("outputs"));assertEquals(List.of("inputs","model"),d.get("missing_inputs"));assertEquals(List.of("proxy_buffer"),((Map<?,?>)d.get("proxy_buffer")).get("missing_inputs"));assertNull(((Map<?,?>)d.get("proxy_buffer")).get("estimated_bytes"));var partial=input();((ObjectNode)partial.get("model")).putNull("pool_nvps_limit");assertEquals(List.of("model.pool_nvps_limit"),data(partial,request()).get("missing_inputs"));}
    @Test void allMeasurementsApprovalPersistenceAndPocClaimsStayUnverified(){var d=data(input(),request());assertEquals(true,d.get("estimate_only"));assertEquals(false,d.get("scenario_saved"));assertEquals(false,d.get("production_capacity_verified"));assertEquals("UNVERIFIED",d.get("measurement_verification"));assertEquals("UNVERIFIED",d.get("model_approval_status"));assertEquals("NOT_RUN",d.get("poc_status"));assertNull(d.get("approved_pool_nvps_limit"));assertNull(d.get("measured_capacity"));assertEquals(false,((Map<?,?>)d.get("proxy_buffer")).get("measurement_verified"));assertEquals(false,((Map<?,?>)d.get("proxy_buffer")).get("failover_verified"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void currentPlatformAdminOnlyAndInactiveOrAnonymousDenied(){for(String role:List.of("viewer","tadmin","msp","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,1,true)));assertEquals(403,assertThrows(DomainException.class,()->data(input(),request())).status);}when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,false)));assertEquals(401,assertThrows(DomainException.class,()->data(input(),request())).status);var r=request();r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->data(input(),r)).status);}
    @Test void forgedTenantFieldsAndQueriesCannotOverrideSessionScope(){var r=request();r.addHeader("X-Tenant-ID",ACTOR);assertEquals(TENANT,data(input(),r).get("tenant_id"));assertEquals(400,assertThrows(DomainException.class,()->data(input().put("tenant_id",ACTOR),request())).status);var q=request();q.addParameter("tenant_id",ACTOR);assertEquals(400,assertThrows(DomainException.class,()->data(input(),q)).status);}
    @Test void requiredGroupsAndUnknownNestedFieldsFailClosed(){for(String key:List.of("inputs","model","proxy_buffer")){var v=input();v.remove(key);assertEquals(400,assertThrows(DomainException.class,()->data(v,request())).status);}var extra=input();((ObjectNode)extra.get("model")).put("approved",true);assertThrows(DomainException.class,()->data(extra,request()));var absent=input();((ObjectNode)absent.get("inputs")).remove("hosts");assertThrows(DomainException.class,()->data(absent,request()));}
    @Test void decimalStringsAvoidFloatCoercionExponentWhitespaceAndUnboundedMagnitude(){for(JsonNode bad:List.of(mapper.getNodeFactory().numberNode(10),mapper.getNodeFactory().booleanNode(true),new TextNode("1e3"),new TextNode(" 10"),new TextNode("-1"),new TextNode("01"),new TextNode("1."),new TextNode("1".repeat(41)),new TextNode("0."+"1".repeat(41)))){var v=input();((ObjectNode)v.get("inputs")).set("interval_seconds",bad);assertEquals(400,assertThrows(DomainException.class,()->data(v,request())).status);}var v=input();((ObjectNode)v.get("inputs")).put("hosts","1.0");assertThrows(DomainException.class,()->data(v,request()));}
    @Test void invalidSignsRatiosDayRangesAndDenominatorsAreRejected(){for(String key:List.of("interval_seconds","bytes_per_value")){var v=input();((ObjectNode)v.get("inputs")).put(key,"0");assertThrows(DomainException.class,()->data(v,request()));}for(String key:List.of("trend_ratio","headroom_ratio")){var v=input();((ObjectNode)v.get("inputs")).put(key,"1.01");assertThrows(DomainException.class,()->data(v,request()));}for(JsonNode bad:List.of(new TextNode("1"),mapper.getNodeFactory().numberNode(-1),mapper.getNodeFactory().numberNode(1.5),mapper.getNodeFactory().numberNode(2147483648L))){var v=input();((ObjectNode)v.get("inputs")).set("history_days",bad);assertThrows(DomainException.class,()->data(v,request()));}}
    @Test void zeroCountsDoNotBypassUnknownModelOrBufferParameters(){var v=input();((ObjectNode)v.get("inputs")).put("hosts","0");assertEquals("0",((Map<?,?>)data(v,request()).get("outputs")).get("pools"));((ObjectNode)v.get("model")).putNull("version");assertNull(data(v,request()).get("outputs"));((ObjectNode)v.get("proxy_buffer")).put("site_nvps","0").putNull("bytes_per_value");assertNull(((Map<?,?>)data(v,request()).get("proxy_buffer")).get("estimated_bytes"));}
    @Test void largeCountsAndExactPoolCeilingNeverBecomeUnsafeJsonNumbers(){var v=input();((ObjectNode)v.get("inputs")).put("hosts","9007199254740993").put("items_per_host","1").put("interval_seconds","1");var o=(Map<?,?>)data(v,request()).get("outputs");assertEquals("9007199254740993",o.get("total_items"));((ObjectNode)v.get("inputs")).put("hosts","1");((ObjectNode)v.get("model")).put("pool_nvps_limit","0.9999999999999999999999999999999999999999");assertEquals("2",((Map<?,?>)data(v,request()).get("outputs")).get("pools"));}
    @Test void bufferFactorBelowOneIsExplicitlyFlaggedRatherThanSilentlyReinterpreted(){var v=input();((ObjectNode)v.get("proxy_buffer")).put("margin_factor","0.4");var b=(Map<?,?>)data(v,request()).get("proxy_buffer");assertEquals(true,b.get("margin_factor_below_one"));assertEquals("14400000",b.get("estimated_bytes"));}
    @Test void boundedParserRejectsDuplicateTrailingDeepOversizedAndInvalidVersionText()throws Exception{for(String raw:List.of("{\"inputs\":null,\"inputs\":null}","{} {}","[[[[1]]]]"," ".repeat(16385))){var r=request();r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->CapacityEstimateController.body(r)).status);}var r=request();r.setContent(mapper.writeValueAsBytes(input()));assertEquals(input(),CapacityEstimateController.body(r));for(String label:List.of(""," ","\ufeff","x\n","😀".repeat(101))){var v=input();((ObjectNode)v.get("model")).put("version",label);assertThrows(DomainException.class,()->data(v,request()));}}
}
